import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

const charge = async (h: any, id: string) => (await h.pendingEffects()).find((e: any) => e.from === id && e.kind === 'payment.charge');

test('unknown order and duplicate create', async () => {
  const h = await createHost();
  assert.equal(await h.order('a'), null);
  assert.equal((await h.addItem('a')).ok, false);
  assert.equal(await h.order('a'), null);
  assert.deepEqual(await h.create('a'), { ok: true });
  assert.deepEqual(await h.order('a'), { status: 'draft', items: 0, charges: 0, refunds: 0 });
  assert.equal((await h.create('a')).ok, false);
  assert.deepEqual(await h.pendingEffects(), []);
});

test('items bounds', async () => {
  const h = await createHost();
  await h.create('a');
  assert.equal((await h.removeItem('a')).ok, false);
  assert.equal((await h.place('a')).ok, false);
  for (let i = 0; i < 3; i++) assert.equal((await h.addItem('a')).ok, true);
  assert.equal((await h.addItem('a')).ok, false);
  assert.equal((await h.removeItem('a')).ok, true);
  assert.equal((await h.order('a')).items, 2);
});

test('place, pay, ship', async () => {
  const h = await createHost();
  await h.create('a'); await h.addItem('a'); await h.addItem('a');
  assert.equal((await h.place('a')).ok, true);
  const e = await charge(h, 'a');
  assert.deepEqual(e.data, { amount: 2 });
  assert.deepEqual(await h.order('a'), { status: 'placed', items: 2, charges: 1, refunds: 0 });
  assert.equal((await h.cancel('a')).ok, false);
  assert.equal((await h.ship('a')).ok, false);
  assert.equal((await h.addItem('a')).ok, false);
  await h.completeEffect(e.id, 'ok');
  assert.deepEqual(await h.pendingEffects(), []);
  assert.equal((await h.order('a')).status, 'paid');
  assert.equal((await h.ship('a')).ok, true);
  assert.equal((await h.order('a')).status, 'shipped');
  assert.equal((await h.cancel('a')).ok, false);
});

test('declined, retried, failed', async () => {
  const h = await createHost();
  await h.create('a'); await h.addItem('a');
  assert.equal((await h.retryPayment('a')).ok, false);
  await h.place('a');
  assert.equal((await h.retryPayment('a')).ok, false);
  await h.completeEffect((await charge(h, 'a')).id, 'failed');
  assert.deepEqual(await h.order('a'), { status: 'declined', items: 1, charges: 1, refunds: 0 });
  for (const c of ['cancel', 'ship', 'addItem', 'removeItem', 'place', 'create'])
    assert.equal((await h[c]('a')).ok, false, c);
  assert.deepEqual(await h.pendingEffects(), []);
  assert.equal((await h.retryPayment('a')).ok, true);
  assert.deepEqual(await h.order('a'), { status: 'placed', items: 1, charges: 2, refunds: 0 });
  assert.equal((await h.retryPayment('a')).ok, false);
  const e = await charge(h, 'a');
  assert.deepEqual(e.data, { amount: 1 });
  await h.completeEffect(e.id, 'failed');
  assert.deepEqual(await h.order('a'), { status: 'failed', items: 1, charges: 2, refunds: 0 });
  assert.equal((await h.retryPayment('a')).ok, false);
  assert.equal((await h.cancel('a')).ok, false);
});

test('retry succeeds, then cancel refunds', async () => {
  const h = await createHost();
  await h.create('a'); await h.addItem('a'); await h.addItem('a'); await h.place('a');
  await h.completeEffect((await charge(h, 'a')).id, 'failed');
  await h.retryPayment('a');
  await h.completeEffect((await charge(h, 'a')).id, 'ok');
  assert.deepEqual(await h.order('a'), { status: 'paid', items: 2, charges: 2, refunds: 0 });
  assert.equal((await h.retryPayment('a')).ok, false);
  assert.equal((await h.cancel('a')).ok, true);
  assert.deepEqual(await h.order('a'), { status: 'cancelled', items: 2, charges: 2, refunds: 1 });
});

test('cancel draft and paid', async () => {
  const h = await createHost();
  await h.create('a');
  assert.equal((await h.cancel('a')).ok, true);
