    assert.equal((await h[c]('a')).ok, false, c);
  assert.deepEqual(await h.pendingEffects(), []);
  assert.equal((await h.retryPayment('a')).ok, true);
  assert.deepEqual(await h.order('a'), { status: 'placed', items: 1, charges: 2, refunds: 0 });
  assert.equal((await h.retryPayment('a')).ok, false);
